window.docContents[251].resolve({"/Development-Server/#serve-running":{"contents":"The verso-serve command takes an optional port (8000 by default) and an optional directory (the current directory by default).$ lake exe serve --port 8000 _out/html\n\n\nIf the requested port is already in use, the server scans the following ports for a free one and prints the port it settled on, so several servers started with default settings can run at once.\nPass --strict-port to fail instead.\n\n","context":"Writing Documentation in Lean with Verso\u0009Development Server","header":"9.1. Running the Server","id":"/Development-Server/#serve-running"}});